PRAGMA defer_foreign_keys=TRUE;
CREATE TABLE products (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  name TEXT NOT NULL,
  brand TEXT,
  category TEXT,
  price REAL NOT NULL,
  stock INTEGER DEFAULT 0,
  image_url TEXT,
  description TEXT,
  created_at TEXT DEFAULT CURRENT_TIMESTAMP
, is_hidden INTEGER DEFAULT 0);
CREATE TABLE orders (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  customer_name TEXT NOT NULL,
  customer_phone TEXT NOT NULL,
  customer_address TEXT,
  total REAL NOT NULL,
  status TEXT DEFAULT 'pending',
  created_at TEXT DEFAULT CURRENT_TIMESTAMP
, is_confirmed INTEGER DEFAULT 0, location_lat REAL, location_lng REAL);
CREATE TABLE settings (
  key TEXT PRIMARY KEY,
  value TEXT,
  updated_at TEXT DEFAULT CURRENT_TIMESTAMP
);
CREATE TABLE offer_items (id INTEGER PRIMARY KEY AUTOINCREMENT, offer_id INTEGER NOT NULL, product_id INTEGER NOT NULL, quantity INTEGER NOT NULL, FOREIGN KEY (offer_id) REFERENCES offers(id));
CREATE TABLE IF NOT EXISTS "offers" (id INTEGER PRIMARY KEY AUTOINCREMENT, title TEXT NOT NULL, discount_percent REAL DEFAULT 0, created_at TEXT DEFAULT CURRENT_TIMESTAMP, manual_price REAL DEFAULT NULL);
CREATE TABLE IF NOT EXISTS "order_items" (id INTEGER PRIMARY KEY AUTOINCREMENT, order_id INTEGER NOT NULL, product_id INTEGER, offer_id INTEGER, quantity INTEGER NOT NULL, price REAL NOT NULL, item_name TEXT, FOREIGN KEY (order_id) REFERENCES orders(id));
DELETE FROM sqlite_sequence;
